--
-- Table structure for table `camera_report_hls`
--

DROP TABLE IF EXISTS `camera_report_hls`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `camera_report_hls` (
  `id` int NOT NULL AUTO_INCREMENT,
  `exam_id` int DEFAULT NULL,
  `shift_id` int DEFAULT NULL,
  `city` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `center_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `camera_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `camera_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `camera_category` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tc_code` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ch_code` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `state` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `camera_status` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `events` int DEFAULT '0',
  `rejected_events` int DEFAULT '0',
  `date_time` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Manual entry (dd/mm/yyyy HH:MM:SS)',
  `imageurl` text COLLATE utf8mb4_unicode_ci,
  `detection_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `unique_id` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `pushed_to_client` tinyint(1) NOT NULL DEFAULT '0',
  `remove_from_client` tinyint(1) NOT NULL DEFAULT '0',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `shift_id` (`shift_id`),
  KEY `idx_camera_id` (`camera_id`),
  KEY `idx_push_status` (`pushed_to_client`,`created_at` DESC),
  KEY `idx_detection_type` (`detection_type`,`pushed_to_client`),
  KEY `idx_camera_time` (`camera_id`,`created_at` DESC),
  KEY `idx_exam_shift_push` (`exam_id`,`shift_id`,`pushed_to_client`,`created_at` DESC),
  KEY `idx_unique_id` (`unique_id`),
  CONSTRAINT `camera_report_hls_ibfk_1` FOREIGN KEY (`exam_id`) REFERENCES `exams` (`id`) ON DELETE SET NULL,
  CONSTRAINT `camera_report_hls_ibfk_2` FOREIGN KEY (`shift_id`) REFERENCES `exam_shifts` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
