  KEY `idx_shift_id` (`shift_id`),
  KEY `idx_script_id` (`script_id`),
  KEY `idx_status` (`status`),
  KEY `idx_assignment_date` (`assignment_date`),
  KEY `idx_is_active` (`is_active`),
